## Code Example
```javascript
function minCostPartition(A, k) {
  const n = A.length;
  const S = new Array(n+1).fill(0);
  for (let i = 1; i <= n; i++) S[i] = S[i-1] + A[i-1];
  const INF = 1e18;
  const dp = Array.from({ length: n+1 }, () => Array(k+1).fill(INF));
  const prev = Array.from({ length: n+1 }, () => Array(k+1).fill(-1));
  dp[0][0] = 0;
  for (let i = 1; i <= n; i++) {
    for (let t = 1; t <= k && t <= i; t++) {
      for (let j = 0; j < i; j++) {
        const diff = S[i] - S[j];
        const cost = diff * diff;
        const val = dp[j][t-1] + cost;
        if (val < dp[i][t]) {
          dp[i][t] = val;
          prev[i][t] = j;
        }
      }
    }
  }
  // reconstruction omitted for brevity
  return { cost: dp[n][k] };
}
```

## Why This Is Asked

Tests DP with non-uniform skip constraints and reconstruction, common in scheduling and resource-constrained selection. It ensures you can encode constraints as a forward DP and extract the chosen indices.

## Key Concepts

- DP with forward state (i, r)
- Transition skipping vs taking with jump i+gap[i]
- Path reconstruction and complexity

## Code Example

```javascript
function maxSumWithGaps(A, gap, k) {
  const n = A.length;
  const NEG = -Infinity;
  const memo = Array.from({ length: n + 2 }, () => Array(k + 1).fill(null));

  const go = (i, r) => {
    if (r === 0) return 0;
    if (i > n) return NEG;
    if (memo[i][r] != null) return memo[i][r];
    const skip = go(i + 1, r);
    const take = A[i - 1] + go(Math.min(n + 1, i + gap[i - 1]), r - 1);
    const best = Math.max(skip, take);
    memo[i][r] = best;
    return best;
  };

  const best = go(1, k);
  return { best, memo };
}
```

